package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPointExchangeCatalogTest extends JdbcCouponInventoryTest {
 PointExchangeCatalog catalog;
 @BeforeEach void catalogSetup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_catalog_audit");jdbc.update("DELETE FROM point_exchange_catalog");jdbc.update("UPDATE operator_account SET can_points=1 WHERE id=1");catalog=new PointExchangeCatalog(db,coupons,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 long selected(){long id=publish(2);coupons.pool(operator,id,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));return id;}
 ObjectNode config(long id){return json.createObjectNode().put("coupon_id",id).put("publication_revision",2).put("pool_revision",1).put("points_cost",17).put("per_owner_limit",2).put("source_note","合成测试兑换来源").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(3600).toString());}
 long createCatalog(long id){var b=config(id);PointExchangeCatalog.input(b.toString(),false);return catalog.create(operator,key(),b).path("data").path("id").asLong();}
 void publishCatalog(long id){catalog.status(operator,id,key(),statusBody(1,"PUBLISHED"));}
 @Test void pointsPermissionReadsOnlySelectedRealSourcesWithoutCouponPrivilegesOrAwards(){long selected=selected();publish(2);create(2);jdbc.update("UPDATE operator_account SET can_coupon=0 WHERE id=1");var sources=catalog.sources(operator,1);assertEquals(1L,sources.get("total"));assertTrue(db.json(sources).contains("\"coupon_id\":"+selected));long id=createCatalog(selected);publishCatalog(id);assertEquals(0,count("coupon_issue"));assertEquals(0,count("point_verified_entry"));assertEquals(0,count("point_exchange"));assertEquals(0,count("point_verified_account"));assertTrue(db.json(catalog.list(operator,1)).contains("OWNER_COUPON_LIFETIME"));assertFalse(db.json(catalog.list(operator,1)).contains("submission_hash"));}
 @Test void couponAndInvitePrivilegesDoNotGrantPointsAndReplaysReauthorize(){long c=selected();String k=key();var b=config(c);catalog.create(operator,k,b);jdbc.update("UPDATE operator_account SET can_points=0,can_coupon=1,can_invite=1 WHERE id=1");assertEquals(403,code(()->catalog.sources(operator,1)));assertEquals(403,code(()->catalog.list(operator,1)));assertEquals(403,code(()->catalog.create(operator,k,b)));jdbc.update("UPDATE operator_account SET can_points=1 WHERE id=1");jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",operator.session());assertEquals(401,code(()->catalog.create(operator,k,b)));}
 @Test void bothCouponKindsKeepTheirOwnPublishedTerms(){long amount=selected();long a=createCatalog(amount);var service=draft(1);((ObjectNode)service.get("terms")).put("type","SERVICE").put("amount","0.00").put("min_spend","0.00");long c=coupons.create(merchant,key(),service).path("data").path("coupon_id").asLong();coupons.status(merchant,c,key(),statusBody(1,"PUBLISHED"));coupons.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));long b=createCatalog(c);publishCatalog(a);publishCatalog(b);var listed=db.json(catalog.list(operator,1));assertTrue(listed.contains("SERVICE"));assertTrue(listed.contains("DISCOUNT"));assertTrue(listed.contains("0.00"));}
 @Test void sourceVersionsSelectionStatusAndActiveIssuerAreRechecked(){long c=publish(2);assertEquals(409,code(()->createCatalog(c)));coupons.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));assertEquals(409,code(()->catalog.create(operator,key(),config(c).put("publication_revision",3))));long id=createCatalog(c);coupons.pool(operator,c,key(),json.createObjectNode().put("selected",false).put("expected_pool_revision",1));assertEquals(409,code(()->publishCatalog(id)));coupons.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",2));assertEquals(409,code(()->publishCatalog(id)));var b=config(c).put("pool_revision",3).put("expected_revision",1);catalog.update(operator,id,key(),b);jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id=1");assertEquals(404,code(()->catalog.status(operator,id,key(),statusBody(2,"PUBLISHED"))));assertEquals(0L,catalog.sources(operator,1).get("total"));jdbc.update("UPDATE merchant_project SET on_shelf=1 WHERE id=1");coupons.status(merchant,c,key(),statusBody(2,"STOPPED"));assertEquals(409,code(()->catalog.status(operator,id,key(),statusBody(2,"PUBLISHED"))));}
 @Test void windowWithinCouponIsRequiredAndFutureSourcesCanBeConfigured(){long c=selected();assertEquals(409,code(()->catalog.create(operator,key(),config(c).put("valid_to",clock.value.plusSeconds(3601).toString()))));assertEquals(409,code(()->catalog.create(operator,key(),config(c).put("valid_from",clock.value.minusSeconds(61).toString()))));var draft=draft(2);((ObjectNode)draft.get("terms")).put("valid_from",clock.value.plusSeconds(120).toString());long future=coupons.create(merchant,key(),draft).path("data").path("coupon_id").asLong();coupons.status(merchant,future,key(),statusBody(1,"PUBLISHED"));coupons.pool(operator,future,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));var b=config(future).put("valid_from",clock.value.plusSeconds(120).toString());long id=catalog.create(operator,key(),b).path("data").path("id").asLong();publishCatalog(id);assertEquals(2L,catalog.sources(operator,1).get("total"));clock.value=clock.value.plusSeconds(3600);assertEquals(0L,catalog.sources(operator,1).get("total"));assertEquals(409,code(()->createCatalog(c)));}
 @Test void draftCasPublicationFreezeStopAndReplacementPreserveTemplateLimitScope(){long c=selected(),id=createCatalog(c);var b=config(c).put("expected_revision",1).put("points_cost",19);catalog.update(operator,id,key(),b);assertEquals(409,code(()->catalog.update(operator,id,key(),b)));catalog.status(operator,id,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->catalog.update(operator,id,key(),b.put("expected_revision",3))));long replacement=createCatalog(c);assertEquals(409,code(()->publishCatalog(replacement)));catalog.status(operator,id,key(),statusBody(3,"STOPPED"));assertEquals(409,code(()->catalog.status(operator,id,key(),statusBody(4,"PUBLISHED"))));publishCatalog(replacement);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM point_exchange_catalog WHERE status='PUBLISHED'",Integer.class));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM point_exchange_catalog WHERE coupon_id=?",Integer.class,c));}
 @Test void stopRemainsAvailableAfterSourceBecomesUnavailable(){long c=selected(),id=createCatalog(c);publishCatalog(id);jdbc.update("UPDATE merchant SET status=0 WHERE id=1");clock.value=clock.value.plusSeconds(3600);catalog.status(operator,id,key(),statusBody(2,"STOPPED"));assertEquals("STOPPED",catalog.row(id,false).get("status"));}
 @Test void permanentCreationReplayReturnsOriginalEvenAfterExpiryAndSourceRemoval(){long c=selected();String k=key();var b=config(c);var first=catalog.create(operator,k,b);long id=first.path("data").path("id").asLong();publishCatalog(id);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");jdbc.update("UPDATE merchant SET status=0 WHERE id=1");clock.value=clock.value.plusSeconds(3600);assertEquals(first.path("data"),catalog.create(operator,k,b).path("data"));assertEquals(1,count("point_exchange_catalog"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='POINT_CATALOG_CREATE'",Integer.class));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,code(()->catalog.create(operator,k,b.deepCopy().put("points_cost",18))));}
 @Test void auditFailureRollsBackCreationReceiptAndPublish(){long c=selected();String k=key();jdbc.execute("CREATE TRIGGER fail_catalog_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->catalog.create(operator,k,config(c))));assertEquals(0,count("point_exchange_catalog"));jdbc.execute("DROP TRIGGER fail_catalog_audit");long id=catalog.create(operator,k,config(c)).path("data").path("id").asLong();jdbc.execute("CREATE TRIGGER fail_catalog_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->publishCatalog(id)));assertEquals("DRAFT",catalog.row(id,false).get("status"));}
 @Test void concurrentOperatorsCannotPublishTwoCatalogsForOneCoupon()throws Exception{long c=selected(),first=createCatalog(c),second=createCatalog(c);jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_points) VALUES(2,'catalog-peer','unused','13800000001',1)");var peerOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),java.time.Instant.now().plusSeconds(600));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();try{publishCatalog(first);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var b=pool.submit(()->{start.await();try{catalog.status(peerOp,second,key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);}finally{pool.shutdownNow();}}
 @Test void strictInputRejectsUnpricedFractionalForgedAndMalformedRules(){var b=config(1);for(String raw:List.of(b.deepCopy().put("coupon_id",0).toString(),b.deepCopy().put("points_cost",0).toString(),b.deepCopy().put("points_cost",1.5).toString(),b.deepCopy().put("per_owner_limit",1000001).toString(),b.deepCopy().put("balance",99).toString(),b.deepCopy().put("source_note"," x ").toString(),b.deepCopy().put("valid_to",clock.value.toString()).toString(),b+"{}"))assertThrows(Exception.class,()->PointExchangeCatalog.input(raw,false));assertThrows(Exception.class,()->catalog.list(operator,0));}
}
